<script setup lang="ts">
import {onMounted,reactive,ref,watch} from 'vue'
import {getAuthContextVersion} from '@/api/http'
import {milestoneBody,type MilestoneBody} from '@/api/v3-milestones'
import {useV3MilestonesStore} from '@/stores/v3Milestones'
import {useAuthStore} from '@/stores/auth'
const auth=useAuthStore(),store=useV3MilestonesStore(),mounted=ref(false),submitted=ref('')
const blank=():MilestoneBody=>({title:'',date:'',endDate:'',content:'',mediaURL:'',mediaType:'',mediaCaption:'',link:''}),form=reactive(blank())
async function submit(){if(store.busy||store.pending)return;try{submitted.value=JSON.stringify(milestoneBody({...form}))}catch{submitted.value=''}await store.submit({...form})}
watch(()=>store.completed,c=>{if(c&&JSON.stringify(c.body)===submitted.value){let current='';try{current=JSON.stringify(milestoneBody({...form}))}catch{}if(current===submitted.value)Object.assign(form,blank());submitted.value=''}})
watch(()=>JSON.stringify([getAuthContextVersion(),!!auth.accessToken,auth.account?.oId||'']),()=>{Object.assign(form,blank());submitted.value=''}, {flush:'sync'});onMounted(()=>{mounted.value=true})
</script>
<template><form v-if="mounted&&auth.accessToken&&auth.account?.oId" class="milestone-form" @submit.prevent="submit"><h2>提交大事记</h2><p>正文使用Markdown，审核通过后才进入公开时间线。提交结果与当前审核状态分开显示。</p><label>标题<input v-model="form.title" maxlength="255" required :disabled="store.busy||!!store.pending"/></label><label>开始日期<input v-model="form.date" type="date" min="0001-01-01" max="9999-12-31" required :disabled="store.busy||!!store.pending"/></label><label>结束日期（可选）<input v-model="form.endDate" type="date" min="0001-01-01" max="9999-12-31" :disabled="store.busy||!!store.pending"/></label><label>正文（Markdown，最多102400字符）<textarea v-model="form.content" rows="8" maxlength="102400" required :disabled="store.busy||!!store.pending"/></label><label>媒体地址（可选）<input v-model="form.mediaURL" maxlength="1024" :disabled="store.busy||!!store.pending"/></label><label>媒体类型<select v-model="form.mediaType" :disabled="store.busy||!!store.pending"><option value="">无</option><option value="image">图片</option><option value="video">视频</option></select></label><label>媒体说明（可选）<input v-model="form.mediaCaption" maxlength="255" :disabled="store.busy||!!store.pending"/></label><label>相关链接（可选）<input v-model="form.link" maxlength="1024" :disabled="store.busy||!!store.pending"/></label><p>媒体和相关链接可用HTTP、HTTPS或站内路径；提供媒体地址时须选择类型。</p><button type="submit" :disabled="store.busy||!!store.pending">{{ store.busy?'提交中…':'提交审核' }}</button></form></template>
<style scoped lang="scss">.milestone-form{display:flex;flex-direction:column;gap:10px}h2{font-size:17px;margin:0}p{margin:0;color:var(--fp-muted);font-size:13px}label{display:flex;flex-direction:column;gap:6px}input,textarea,select,button{box-sizing:border-box;font:inherit;padding:8px;border:1px solid var(--fp-border);border-radius:6px;color:var(--fp-text);background:var(--fp-bg)}button{align-self:flex-start}textarea{width:100%}</style>
